// ── Starter food + recipe pool (v3.10.1055) ───────────────────────────────────────────────────────────────
// One shared pool serves the demos, onboarding and every starter pack (packs flag "foodPool": true). Offline: the data is embedded above.
// Typical reference values per 100 g; items are marked source:'starter' so they can be removed in one tap. Generated by tools/gen_food_pool.py.
function mhPoolStyleFor(lsId) { return ({ keto: 'keto', mediterranean: 'med', higher_protein: 'hp', lower_calorie: 'lcal', balanced: 'bal' })[lsId] || ''; }
function mhPoolWanted(style) { return style === 'keto' ? ['all', 'keto'] : (style === 'med' || style === 'hp' || style === 'lcal') ? ['all', style, 'bal'] : ['all', 'med', 'hp', 'lcal', 'bal']; }
function mhPoolFoods(style) {
  // keto leaves out foods over 15 g carbs per 100 g, but always keeps anything the chosen recipes need
  const want = mhPoolWanted(style), need = new Set();
  MH_FOOD_POOL.recipes.filter(r => r.t.some(t => want.includes(t))).forEach(r => r.i.forEach(([n]) => need.add(n)));
  return MH_FOOD_POOL.foods.filter(x => !(style === 'keto' && x.c > 15 && !need.has(x.n))).map(x => {
    const sc = v => Math.round(v * x.g) / 100;
    return { name: x.n, kcal: sc(x.k), protein: sc(x.p), carbs: sc(x.c), fat: sc(x.f), portion: x.g + 'g', per100g: false, locked: false, source: 'starter' };
  });
}
function mhPoolRecipes(style, idPrefix) {
  const want = mhPoolWanted(style);
  const by = {}; MH_FOOD_POOL.foods.forEach(x => { by[x.n] = x; });
  const sc = (v, g) => Math.round(v * g * 10 / 100) / 10;
  return MH_FOOD_POOL.recipes.filter(r => r.t.some(t => want.includes(t))).map((r, i) => {
    const t = { kcal: 0, protein: 0, carbs: 0, fat: 0 };
    const ings = r.i.map(([n, g]) => { const x = by[n] || { k: 0, p: 0, c: 0, f: 0 }; const o = { name: n, amount: g, kcal: sc(x.k, g), protein: sc(x.p, g), carbs: sc(x.c, g), fat: sc(x.f, g) }; t.kcal += o.kcal; t.protein += o.protein; t.carbs += o.carbs; t.fat += o.fat; return o; });
    const R1 = v => Math.round(v * 10) / 10;
    return { id: (idPrefix || 'pool_r') + (i + 1), name: r.n, servings: r.s, ingredients: ings, total: { kcal: R1(t.kcal), protein: R1(t.protein), carbs: R1(t.carbs), fat: R1(t.fat) }, source: 'starter' };
  });
}
// Adds the pool to the real library and recipes (never replaces; skips names already there). Returns counts.
function mhPoolApply(style) {
  const key = x => String(x.name || '').toLowerCase().trim();
  const lib = mhPackLoadCurrent('library').slice(), have = new Set(lib.map(key)); let nf = 0, nr = 0;
  mhPoolFoods(style).forEach(x => { if (!have.has(key(x))) { lib.push(x); have.add(key(x)); nf++; } });
  saveLibrary(lib);
  const rec = mhPackLoadCurrent('recipes').slice(), haveR = new Set(rec.map(key)), ids = new Set(rec.map(r => r.id));
  mhPoolRecipes(style, 'pool_r').forEach(r => { if (!haveR.has(key(r))) { if (ids.has(r.id)) r.id = 'pool_r_' + Date.now().toString(36) + nr; rec.push(r); haveR.add(key(r)); ids.add(r.id); nr++; } });
  saveRecipes(rec);
  ['renderLibrary'].forEach(fn => { try { if (typeof window[fn] === 'function') window[fn](); } catch (e) {} });
  return { foods: nf, recipes: nr };
}
function mhPoolRemove() {
  const lib = mhPackLoadCurrent('library').filter(x => x.source !== 'starter'), rec = mhPackLoadCurrent('recipes').filter(x => x.source !== 'starter');
  const nf = mhPackLoadCurrent('library').length - lib.length, nr = mhPackLoadCurrent('recipes').length - rec.length;
  saveLibrary(lib); saveRecipes(rec);
  try { if (typeof renderLibrary === 'function') renderLibrary(); } catch (e) {}
  return { foods: nf, recipes: nr };
}
// Demo personas: low-carb personas get the keto set; others the everyday set (or the one matching a chosen lifestyle).
function _demoPoolStyle() {
  try {
    const p = (typeof DEMO_PERSONAS !== 'undefined') ? DEMO_PERSONAS.find(x => x.id === _demoPersonaId) : null;
    if (p && p.carbStyle === 'low') return 'keto';
  } catch (e) {}
  return mhPoolStyleFor(localStorage.getItem('mh_lifestyle') || '');
}
function generateDemoLibrary() { return mhPoolFoods(_demoPoolStyle()).map(x => Object.assign(x, { source: 'demo' })); }
function generateDemoRecipes() { return mhPoolRecipes(_demoPoolStyle(), 'demo_r').map(r => Object.assign(r, { source: 'demo' })); }
